            E(R(float3( 0.0, -p.y, -p.z) * ms), R(float3( 0.0, -p.y, p.z) * ms), 21.0);
            E(R(float3( 0.0, -p.y, -p.z) * ms), R(float3( p.z, 0.0, p.y) * ms), 22.0);
            E(R(float3( 0.0, -p.y, -p.z) * ms), R(float3(-p.z, 0.0, p.y) * ms), 23.0);
            E(R(float3(-p.z, 0.0, -p.y) * ms), R(float3( p.z, 0.0, -p.y) * ms), 24.0);
            E(R(float3(-p.z, 0.0, p.y) * ms), R(float3( p.z, 0.0, p.y) * ms), 25.0);
            E(R(float3(-p.z, 0.0, -p.y) * ms), R(float3( 0.0, p.y, p.z) * ms), 26.0);
            E(R(float3(-p.z, 0.0, -p.y) * ms), R(float3( 0.0, -p.y, p.z) * ms), 27.0);
            E(R(float3( p.z, 0.0, -p.y) * ms), R(float3( 0.0, p.y, p.z) * ms), 28.0);
            E(R(float3( p.z, 0.0, -p.y) * ms), R(float3( 0.0, -p.y, p.z) * ms), 29.0);
            return;
        }
    }
    void amzRender() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float4 orig = layerAt(uv);
        float ps = pxs();
        float unit = 0.5 * min(W.x, W.y);
        float2 sp = (uv - 0.5) * W - float2(amzp_position.x, -amzp_position.y) * ps;
        sp = nmRot(sp, radians(amzp_angle)) / max(amzp_stretch, float2(0.01));
        PP = sp / unit;
        AAU = 1.0 / unit;
        LWU = 0.5 * amzp_lineW * ps * AAU;
        GSU = amzp_glowSize * ps * AAU;
        CUT = LWU + AAU + (amzp_glowAmt > 0.0 ? GSU * 7.0 : 0.0);
        LAYC = orig.a > 0.0001 ? orig.rgb / orig.a : float3(1.0);
        LAYC = clamp(mix(float3(dot(LAYC, float3(0.2126, 0.7152, 0.0722))), LAYC, 1.4) * 1.25, 0.0, 1.0);
        TIME = TT();
        MO = TIME * amzp_morphSpeed * 0.1;
        W4 = radians(amzp_spin4) * TIME;
        float br = 1.0 + amzp_breathe * 0.3 * sin(TIME * 6.28318531 * 0.5);
        SCL = 0.6 * max(amzp_scale * 2.0, 0.002) * br;
        DCAM = SCL * 4.0 / max(amzp_persp, 0.01);
        float3 ang = radians(float3(amzp_rotX, amzp_rotY, amzp_rotZ) + float3(amzp_spinX, amzp_spinY, amzp_spinZ) * TIME);
        MR = rotM(ang);
        ACC = float3(0.0);
        float s0 = SCL;
        float w0 = W4;
        for (int pass = 0; pass < 2; pass++) {
            if (pass == 1) {
                if (!(amzp_innerShell>0.5)) break;
                SCL = s0 * amzp_innerScale;
                MR = rotM(-ang * 1.3 + float3(0.6, 0.3, 0.0));
                W4 = -w0 * 1.3;
            }
            drawShape();
        }
        SCL = s0;
        float3 L = 1.0 - exp(-ACC * 1.2);
        float la = clamp(max(L.r, max(L.g, L.b)), 0.0, 1.0);
        float4 G = float4(L, la) + float4(amzp_bgCol.rgb * amzp_bgCol.a, amzp_bgCol.a) * (1.0 - la);
        amzOutput = nmBlend(orig, nmGradMap(G));
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
